// Library style only: retain expression order while flattening the translator's
// pure String concatenation macros. Source header syntax is still generated by
// the checked JavaScript rules, never rewritten after production emission.
export function splitRustSourceHeaderStyleArguments(text) {
  const result = []; let start = 0; let depth = 0; let quoted = false; let escaped = false;
  for (let at = 0; at < text.length; at += 1) {
    const character = text[at];
    if (quoted) { if (escaped) escaped = false; else if (character === '\\') escaped = true; else if (character === '"') quoted = false; continue; }
    if (character === '"') quoted = true;
    else if ('([{'.includes(character)) depth += 1;
    else if (')]}'.includes(character)) depth -= 1;
    else if (character === ',' && depth === 0) { result.push(text.slice(start, at).trim()); start = at + 1; }
  }
  result.push(text.slice(start).trim());
  return result.filter(Boolean);
}

export function stripRustSourceHeaderStyleParentheses(text) {
  let result = text.trim();
  while (result.startsWith('(') && result.endsWith(')')) {
    if (splitRustSourceHeaderStyleArguments(`${result.slice(1, -1)},`).length !== 1) break;
    let depth = 0; let complete = true; let quoted = false; let escaped = false;
    for (let at = 0; at < result.length; at += 1) {
      const character = result[at];
      if (quoted) { if (escaped) escaped = false; else if (character === '\\') escaped = true; else if (character === '"') quoted = false; continue; }
      if (character === '"') quoted = true;
      else if (character === '(') depth += 1;
      else if (character === ')' && --depth === 0 && at !== result.length - 1) { complete = false; break; }
    }
    if (!complete) break;
    result = result.slice(1, -1).trim();
  }
  return result;
}

export function flattenRustSourceHeaderStyleFormat(text) {
  const parts = expression => {
    const bare = stripRustSourceHeaderStyleParentheses(expression);
    if (bare.startsWith('format!(') && bare.endsWith(')')) {
      const arguments_ = splitRustSourceHeaderStyleArguments(bare.slice(8, -1));
      if (/^"(?:[^"\\]|\\.)*"$/u.test(arguments_[0])) {
        const format = JSON.parse(arguments_[0]); const result = []; let literal = ''; let argument = 1; let valid = true;
        const flush = () => { if (literal) result.push({ literal }); literal = ''; };
        for (let at = 0; at < format.length; at += 1) {
          if (format.slice(at, at + 2) === '{{' || format.slice(at, at + 2) === '}}') { literal += format[at]; at += 1; }
          else if (format[at] === '{') {
            const end = format.indexOf('}', at); if (end < 0) { valid = false; break; }
            const name = format.slice(at + 1, end); flush();
            if (!name && argument < arguments_.length) result.push(...parts(arguments_[argument++]));
            else if (/^[A-Za-z_][A-Za-z0-9_]*$/u.test(name)) result.push({ expression: name });
            else { valid = false; break; }
            at = end;
          } else if (format[at] === '}') { valid = false; break; }
          else literal += format[at];
        }
        flush(); if (valid && argument === arguments_.length) return result;
      }
    }
    const literal = /^String::from\(("(?:[^"\\]|\\.)*")\)$/u.exec(bare);
    return literal ? [{ literal: JSON.parse(literal[1]) }] : [{ expression: bare }];
  };
  let format = ''; const arguments_ = [];
  for (const part of parts(text)) {
    if (part.literal !== undefined) format += part.literal.replaceAll('{', '{{').replaceAll('}', '}}');
    else if (/^[A-Za-z_][A-Za-z0-9_]*$/u.test(part.expression)) format += `{${part.expression}}`;
    else { format += '{}'; arguments_.push(part.expression); }
  }
  return `format!(${JSON.stringify(format)}${arguments_.length ? ', ' + arguments_.join(', ') : ''})`;
}
